SELECT ip.id as inspectParameterId, ip.name as inspectParameterName, ip.code as inspectParameterCode, MAX(COALESCE(CONVERT(isp.standard_rule USING utf8mb4), CONVERT(sssp.standard_rule USING utf8mb4))) as standardRule, ii.id as inspectItemId, ii.name as inspectItemName, ii.code as inspectItemCode FROM lm_inspect_parameter ip INNER JOIN lm_task t ON ip.id = t.parameter_id INNER JOIN lm_inspect_item ii ON t.inspect_item_id = ii.id INNER JOIN lm_inspection_order io ON t.inspection_order_id = io.id LEFT JOIN lm_inspection_scheme_parameter isp ON isp.id = t.parameter_config_id AND isp.is_deleted = 0 LEFT JOIN lm_stability_scheme_parameter sssp ON sssp.id = t.parameter_config_id AND sssp.is_deleted = 0 WHERE t.is_deleted = 0 AND ip.is_deleted = 0 AND ii.is_deleted = 0 AND io.is_deleted = 0
and t.status not in('PENDING_ASSIGNMENT','RETURN_PENDING_APPROVAL')
AND ( EXISTS ( SELECT 1 FROM lm_inspection_scheme_item_teams sit WHERE sit.inspect_item_id = t.inspect_item_id AND sit.version_id = io.scheme_version_id AND sit.is_deleted = 0 AND sit.team_id IN
#{teamId}
) OR EXISTS ( SELECT 1 FROM lm_stability_scheme_item_teams ssit WHERE ssit.inspect_item_id = t.inspect_item_id AND ssit.version_id = io.scheme_version_id AND ssit.is_deleted = 0 AND ssit.team_id IN
#{teamId}
) )
AND t.owner_id = #{query.currentUserId}
AND ii.name LIKE CONCAT('%', #{query.inspectItemName}, '%')
AND ip.name LIKE CONCAT('%', #{query.parameterName}, '%')
AND io.order_no LIKE CONCAT('%', #{query.inspectionOrderNo}, '%')
AND io.batch_no LIKE CONCAT('%', #{query.batchNo}, '%')
AND io.create_time >= #{query.requestStartTime}
AND io.create_time <= #{query.requestEndTime}
AND io.material_id IN
#{materialId}
AND t.status IN
#{st}
AND t.status = 'TO_REVIEW'
AND ((t.judged_abnormal = 1 AND t.status != 'TERMINATED') OR t.status IN ('REVIEW_REJECTED','SAMPLE_AUDIT_REJECTED'))
AND t.judged_abnormal = 0
GROUP BY ip.id, ip.name, ip.code, ii.id, ii.name, ii.code ORDER BY ii.code ASC, ip.code ASC

SELECT DISTINCT t.id, t.inspection_order_id AS inspectionOrderId, io.order_no AS orderNo, m.name AS materialName, m.code AS materialCode, m.specification AS materialSpec, io.batch_no AS batchNo, io.create_time AS requestTime, io.create_by AS requestUserId, t.status, t.judged_abnormal AS abnormal, t.judged_result AS judgedResult, t.judged_time AS judgedTime, t.test_time AS testTime, t.owner_id AS ownerId, t.owner_name AS ownerName, t.reviewed_by AS reviewedBy, t.reviewed_time AS reviewedTime, t.reviewed_abnormal_reason AS reviewRejectReason, le.entry_time AS entryTime, t.scheme_version_id AS schemeVersionId, t.inspect_item_id AS inspectItemId, t.inspect_item_code AS inspectItemCode, t.item_config_id AS itemConfigId, t.parameter_id AS parameterId, t.parameter_code AS parameterCode, ip.name AS parameterName, t.parameter_config_id AS parameterConfigId, COALESCE(isp.standard_rule, sssp.standard_rule) AS standardRule, t.is_executable AS isExecutable, t.is_reportable AS isReportable, t.assigner_id AS assignerId, t.assigner_name AS assignerName, t.assign_time AS assignTime, t.claim_time AS claimTime, t.complete_time AS completeTime, t.terminate_time AS terminateTime, t.terminate_reason AS terminateReason, t.return_reason AS returnReason, t.reject_reason AS rejectReason, t.remark AS remark, t.execute_method AS executeMethod FROM lm_task t INNER JOIN lm_inspection_order io ON t.inspection_order_id = io.id LEFT JOIN lm_inspect_material m ON io.material_id = m.id LEFT JOIN lm_inspect_parameter ip ON t.parameter_id = ip.id LEFT JOIN lm_inspect_item ii ON t.inspect_item_id = ii.id LEFT JOIN lm_inspection_scheme_parameter isp ON isp.id = t.parameter_config_id AND isp.is_deleted = 0 LEFT JOIN lm_stability_scheme_parameter sssp ON sssp.id = t.parameter_config_id AND sssp.is_deleted = 0 LEFT JOIN ( SELECT ier.task_id, MAX(COALESCE(ier.update_time, ier.create_time)) AS entry_time FROM lm_inspection_entry_record ier WHERE ier.is_deleted = 0 GROUP BY ier.task_id ) le ON le.task_id = t.id WHERE t.is_deleted = 0 AND io.is_deleted = 0 AND ip.is_deleted = 0 AND ii.is_deleted = 0 AND t.parameter_id = #{inspectParameterId} AND t.inspect_item_id = #{inspectItemId}
and t.status not in('PENDING_ASSIGNMENT','RETURN_PENDING_APPROVAL')
AND ( EXISTS ( SELECT 1 FROM lm_inspection_scheme_item_teams sit WHERE sit.inspect_item_id = t.inspect_item_id AND sit.version_id = io.scheme_version_id AND sit.is_deleted = 0 AND sit.team_id IN
#{teamId}
) OR EXISTS ( SELECT 1 FROM lm_stability_scheme_item_teams ssit WHERE ssit.inspect_item_id = t.inspect_item_id AND ssit.version_id = io.scheme_version_id AND ssit.is_deleted = 0 AND ssit.team_id IN
#{teamId}
) )
AND t.owner_id = #{query.currentUserId}
AND ii.name LIKE CONCAT('%', #{query.inspectItemName}, '%')
AND io.order_no LIKE CONCAT('%', #{query.inspectionOrderNo}, '%')
AND io.batch_no LIKE CONCAT('%', #{query.batchNo}, '%')
AND io.create_time >= #{query.requestStartTime}
AND io.create_time <= #{query.requestEndTime}
AND io.material_id IN
#{materialId}
AND t.status IN
#{st}
AND t.status = 'TO_REVIEW'
AND ((t.judged_abnormal = 1 AND t.status != 'TERMINATED') OR t.status IN ('REVIEW_REJECTED','SAMPLE_AUDIT_REJECTED'))
AND t.judged_abnormal = 0
ORDER BY io.create_time DESC, io.order_no DESC

