) )

SELECT COUNT(DISTINCT t.id) FROM lm_task t LEFT JOIN lm_inspect_item ii ON t.inspect_item_id = ii.id LEFT JOIN lm_inspect_parameter ip ON t.parameter_id = ip.id LEFT JOIN lm_inspection_order io ON t.inspection_order_id = io.id LEFT JOIN lm_inspect_material m ON io.material_id = m.id WHERE t.is_deleted = 0 AND ((t.judged_abnormal = 1 AND t.status != 'TERMINATED') OR t.status IN ('REVIEW_REJECTED','SAMPLE_AUDIT_REJECTED'))
AND ii.name LIKE CONCAT('%', #{query.inspectItemName}, '%')
AND ip.name LIKE CONCAT('%', #{query.parameterName}, '%')
AND io.material_id IN
#{materialId}
AND io.order_no LIKE CONCAT('%', #{query.inspectionOrderNo}, '%')
AND io.batch_no LIKE CONCAT('%', #{query.batchNo}, '%')
AND io.create_time >= #{query.requestStartTime}
AND io.create_time <= #{query.requestEndTime}
AND ( EXISTS ( SELECT 1 FROM lm_inspection_scheme_item_teams sit INNER JOIN lm_inspection_order io ON t.inspection_order_id = io.id WHERE sit.inspect_item_id = t.inspect_item_id AND sit.version_id = io.scheme_version_id AND sit.is_deleted = 0 AND sit.team_id IN
#{teamId}
) OR EXISTS ( SELECT 1 FROM lm_stability_scheme_item_teams ssit INNER JOIN lm_inspection_order io ON t.inspection_order_id = io.id WHERE ssit.inspect_item_id = t.inspect_item_id AND ssit.version_id = io.scheme_version_id AND ssit.is_deleted = 0 AND ssit.team_id IN
#{teamId}
) )

SELECT COUNT(DISTINCT io.id) FROM lm_inspection_order io LEFT JOIN lm_inspect_material m ON io.material_id = m.id LEFT JOIN lm_task t ON io.id = t.inspection_order_id LEFT JOIN lm_inspect_item ii ON t.inspect_item_id = ii.id LEFT JOIN lm_inspect_parameter ip ON t.parameter_id = ip.id WHERE io.is_deleted = 0 AND t.is_deleted = 0 AND ((t.judged_abnormal = 1 AND t.status != 'TERMINATED') OR t.status IN ('REVIEW_REJECTED','SAMPLE_AUDIT_REJECTED'))
AND ii.name LIKE CONCAT('%', #{query.inspectItemName}, '%')
AND ip.name LIKE CONCAT('%', #{query.parameterName}, '%')
AND io.material_id IN
#{materialId}
AND io.order_no LIKE CONCAT('%', #{query.inspectionOrderNo}, '%')
AND io.batch_no LIKE CONCAT('%', #{query.batchNo}, '%')
AND io.create_time >= #{query.requestStartTime}
AND io.create_time <= #{query.requestEndTime}
AND ( EXISTS ( SELECT 1 FROM lm_inspection_scheme_item_teams sit INNER JOIN lm_inspection_order io ON t.inspection_order_id = io.id WHERE sit.inspect_item_id = t.inspect_item_id AND sit.version_id = io.scheme_version_id AND sit.is_deleted = 0 AND sit.team_id IN
#{teamId}
) OR EXISTS ( SELECT 1 FROM lm_stability_scheme_item_teams ssit INNER JOIN lm_inspection_order io ON t.inspection_order_id = io.id WHERE ssit.inspect_item_id = t.inspect_item_id AND ssit.version_id = io.scheme_version_id AND ssit.is_deleted = 0 AND ssit.team_id IN
#{teamId}
) )

SELECT io.id AS inspectionOrderId, io.order_no AS inspectionOrderNo, io.batch_no AS batchNo, io.create_time AS requestTime, sv.scheme_id AS schemeId, ier.scheme_version_id AS schemeVersionId, ier.inspect_item_id AS inspectItemId, ier.parameter_id AS parameterId, ier.data_point_name AS dataPointName, ier.value_text AS valueText, COALESCE(ier.value_number, CAST(NULLIF(ier.value_text,'') AS DECIMAL(65,20))) AS valueNumber FROM lm_inspection_entry_record ier INNER JOIN lm_inspection_order io ON ier.inspection_order_id = io.id AND io.is_deleted = 0 LEFT JOIN lm_inspection_scheme_version sv ON io.scheme_version_id = sv.id AND sv.is_deleted = 0
ier.is_deleted = 0 AND ier.point_type = 'NUMBER'
AND io.material_id = #{materialId}
AND sv.scheme_id = #{schemeId}
AND ier.inspect_item_id = #{inspectItemId}
AND ier.parameter_id = #{parameterId}
AND ier.data_point_name = #{dataPointName}
AND io.create_time >= #{requestStartTime}
AND io.create_time <= #{requestEndTime}
ORDER BY io.create_time ASC, io.id ASC
